const lockDaoLuPendingFor = `-- name: LockDaoLuPendingFor :many
SELECT id FROM dao_lu_proposals
WHERE status = 'pending' AND (proposer_character_id = ANY($1::uuid[]) OR target_character_id = ANY($1::uuid[]))
ORDER BY id
FOR UPDATE
`

// Accept locks every pending proposal of both characters in id order BEFORE bonding (it supersedes them): two
// concurrent accepts sharing a character serialize here instead of deadlocking on each other's proposal rows.
func (q *Queries) LockDaoLuPendingFor(ctx context.Context, ids []uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, lockDaoLuPendingFor, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const respondDaoLuProposal = `-- name: RespondDaoLuProposal :execrows
UPDATE dao_lu_proposals SET status = $1, responded_at = $2, respond_key = $3
WHERE id = $4 AND status = 'pending'
`

type RespondDaoLuProposalParams struct {
	Status      string      `json:"status"`
	RespondedAt *time.Time  `json:"responded_at"`
	RespondKey  pgtype.Text `json:"respond_key"`
	ID          uuid.UUID   `json:"id"`
}

func (q *Queries) RespondDaoLuProposal(ctx context.Context, arg RespondDaoLuProposalParams) (int64, error) {
	result, err := q.db.Exec(ctx, respondDaoLuProposal,
		arg.Status,
		arg.RespondedAt,
		arg.RespondKey,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const sumSongTuDay = `-- name: SumSongTuDay :one
SELECT COALESCE(sum(seconds), 0)::INT FROM dao_lu_song_tu_claims WHERE character_id = $1 AND game_day = $2
`

type SumSongTuDayParams struct {
	CharacterID uuid.UUID   `json:"character_id"`
	GameDay     pgtype.Date `json:"game_day"`
}

func (q *Queries) SumSongTuDay(ctx context.Context, arg SumSongTuDayParams) (int32, error) {
	row := q.db.QueryRow(ctx, sumSongTuDay, arg.CharacterID, arg.GameDay)
	var column_1 int32
	err := row.Scan(&column_1)
	return column_1, err
}

const supersedeDaoLuProposals = `-- name: SupersedeDaoLuProposals :exec
UPDATE dao_lu_proposals SET status = 'superseded', responded_at = $1
WHERE status = 'pending' AND id <> $2
  AND (proposer_character_id = ANY($3::uuid[]) OR target_character_id = ANY($3::uuid[]))
`

type SupersedeDaoLuProposalsParams struct {
	Now      *time.Time  `json:"now"`
	ExceptID uuid.UUID   `json:"except_id"`
	Ids      []uuid.UUID `json:"ids"`
}

// Once two characters bond, every other pending proposal involving either of them is void.
func (q *Queries) SupersedeDaoLuProposals(ctx context.Context, arg SupersedeDaoLuProposalsParams) error {
	_, err := q.db.Exec(ctx, supersedeDaoLuProposals, arg.Now, arg.ExceptID, arg.Ids)
	return err
}
